/**
 * Config plugin — add Android Share intent-filters to MainActivity.
 *
 * Background
 * ----------
 * `/android` is gitignored in this repo (regenerated by `expo prebuild
 * --clean` on every CI build). The `expo-share-intent` package ships
 * with an EMPTY `node_modules/expo-share-intent/android/src/main/
 * AndroidManifest.xml` and its prebuild plugin only injects iOS share
 * extension scaffolding — Android intent-filters are NEVER added to the
 * MainActivity, so Chatyy doesn't appear in the Android system share
 * sheet (user taps "Compartilhar" in Photos / browser / etc. and Chatyy
 * is missing from the picker).
 *
 * The Kotlin module DOES handle ACTION_SEND / ACTION_SEND_MULTIPLE
 * intents at runtime (see node_modules/expo-share-intent/android/src/
 * main/java/expo/modules/shareintent/ExpoShareIntentModule.kt lines
 * 127-149) — it just needs the launching Activity to advertise the
 * filters. This plugin adds them at prebuild time so survives
 * `expo prebuild --clean`.
 *
 * Filters added (mirrors iosActivationRules in app.json):
 *   - SEND          image/*
 *   - SEND          video/*
 *   - SEND          text/*
 *   - SEND_MULTIPLE image/*
 *   - SEND_MULTIPLE video/*
 *
 * The MainActivity's existing intent-filters (LAUNCHER + deep-link
 * scheme) are preserved — we only APPEND new filter entries.
 *
 * [WAVE 91 2026-05-21] Created in response to user report:
 * "Share foto NO ANDROID trava — não aparece o picker do Chatyy
 *  no share sheet do Android".
 */
const { withAndroidManifest } = require('@expo/config-plugins');

const SHARE_FILTERS = [
  { action: 'android.intent.action.SEND', mimeType: 'image/*' },
  { action: 'android.intent.action.SEND', mimeType: 'video/*' },
  { action: 'android.intent.action.SEND', mimeType: 'text/*' },
  { action: 'android.intent.action.SEND_MULTIPLE', mimeType: 'image/*' },
  { action: 'android.intent.action.SEND_MULTIPLE', mimeType: 'video/*' },
];

module.exports = function withAndroidShareIntents(config) {
  return withAndroidManifest(config, (cfg) => {
    const manifest = cfg.modResults;
    const app = manifest.manifest.application?.[0];
    if (!app || !Array.isArray(app.activity)) return cfg;
    const main = app.activity.find(
      (a) => a.$?.['android:name'] === '.MainActivity'
    );
    if (!main) return cfg;
    if (!Array.isArray(main['intent-filter'])) main['intent-filter'] = [];

    for (const { action, mimeType } of SHARE_FILTERS) {
      const exists = main['intent-filter'].some((f) => {
        const a = (f.action || []).some((x) => x.$?.['android:name'] === action);
        const d = (f.data || []).some(
          (x) => x.$?.['android:mimeType'] === mimeType
        );
        return a && d;
      });
      if (exists) continue;
      main['intent-filter'].push({
        action: [{ $: { 'android:name': action } }],
        category: [{ $: { 'android:name': 'android.intent.category.DEFAULT' } }],
        data: [{ $: { 'android:mimeType': mimeType } }],
      });
    }
    return cfg;
  });
};
